API_PATH = "app/api/game/death-target-availability/route.ts"
API_CONTENT = 'import { NextResponse } from "next/server";\n\nimport { createAdminClient } from "@/lib/supabase/admin";\nimport { createClient } from "@/lib/supabase/server";\nimport { getDeathRules } from "@/lib/death/death-system";\n\nexport const dynamic = "force-dynamic";\n\nexport async function GET(request: Request) {\n  const url = new URL(request.url);\n  const roomId = String(\n    url.searchParams.get("roomId") ?? "",\n  ).trim();\n\n  if (!roomId) {\n    return NextResponse.json(\n      { error: "Missing Location." },\n      { status: 400 },\n    );\n  }\n\n  const supabase = await createClient();\n\n  const {\n    data: { user },\n  } = await supabase.auth.getUser();\n\n  if (!user) {\n    return NextResponse.json(\n      { error: "Not authenticated." },\n      { status: 401 },\n    );\n  }\n\n  const admin = createAdminClient();\n\n  const { data: viewer, error: viewerError } =\n    await admin\n      .from("characters")\n      .select("id,current_room_id")\n      .eq("user_id", user.id)\n      .maybeSingle();\n\n  if (\n    viewerError ||\n    !viewer ||\n    viewer.current_room_id !== roomId\n  ) {\n    return NextResponse.json(\n      { error: "This Location is not currently available." },\n      { status: 403 },\n    );\n  }\n\n  const [rules, charactersResult] =\n    await Promise.all([\n      getDeathRules(),\n      admin\n        .from("characters")\n        .select(\n          "id,life_state,died_at,zero_hp_at",\n        )\n        .eq("current_room_id", roomId)\n        .eq("status", "approved"),\n    ]);\n\n  if (charactersResult.error) {\n    return NextResponse.json(\n      { error: charactersResult.error.message },\n      { status: 500 },\n    );\n  }\n\n  const deadCharacterIds: string[] = [];\n  const beyondEssenceCharacterIds: string[] = [];\n\n  for (const character of charactersResult.data ?? []) {\n    if (character.life_state !== "dead") {\n      continue;\n    }\n\n    deadCharacterIds.push(character.id);\n\n    const startedAt =\n      character.died_at ??\n      character.zero_hp_at;\n\n    if (!startedAt) {\n      beyondEssenceCharacterIds.push(\n        character.id,\n      );\n      continue;\n    }\n\n    const startedMs = Date.parse(startedAt);\n\n    if (\n      Number.isNaN(startedMs) ||\n      Date.now() >\n        startedMs +\n          rules.essenceWindowMinutes *\n            60_000\n    ) {\n      beyondEssenceCharacterIds.push(\n        character.id,\n      );\n    }\n  }\n\n  return NextResponse.json({\n    viewerCharacterId: viewer.id,\n    deadCharacterIds,\n    beyondEssenceCharacterIds,\n  });\n}\n'

def fail(message):
    print("ERROR:", message)
    print("No files were changed.")
    sys.exit(1)

try:
    head = subprocess.run(
        ["git", "rev-parse", "HEAD"],
        cwd=ROOT,
        check=True,
        capture_output=True,
        text=True,
    ).stdout.strip()
except Exception as exc:
    fail(f"Unable to read git HEAD: {exc}")

if head != EXPECTED:
    fail(f"This patch targets {EXPECTED}, but current HEAD is {head}.")

paths = sorted({path for path, _, _, _ in OPS})
for path in paths:
    if not (ROOT / path).exists():
        fail(f"Missing expected file: {path}")

if (ROOT / API_PATH).exists():
    fail(f"{API_PATH} already exists.")

files = {path: (ROOT / path).read_text(encoding="utf-8") for path in paths}
originals = dict(files)

for path, old, new, label in OPS:
    count = files[path].count(old)
    if count != 1:
        fail(f"{label}: expected exactly 1 match in {path}, found {count}.")
    files[path] = files[path].replace(old, new, 1)

# Remaining ordinary target selects in RoomChatForm should also exclude faded corpses.
chat_path = "app/(portal)/game/components/RoomChatForm.tsx"
files[chat_path] = files[chat_path].replace(
    "{presentCharacters.map((entry) => (",
    "{ordinaryTargetCharacters.map((entry) => (",
)

# Sanity checks before writes.
for needle in [
    "ordinaryTargetCharacters",
    "whisperCharacters",
    "beyondEssenceCharacterIds",
    "<WarpingPanel",
    "<ItemExchangePanel",
]:
    if needle not in files[chat_path]:
        fail(f"Sanity check failed: {needle} missing from RoomChatForm.")

warp_path = "app/(portal)/game/components/WarpingPanel.tsx"
if "shapeTargetCharacters" not in files[warp_path]:
    fail("Sanity check failed: Shape target filter missing.")

stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
backup = ROOT / f".faded-corpse-targeting-backup-{stamp}"

for path, original in originals.items():
    if files[path] == original:
        continue
    target = backup / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(original, encoding="utf-8")

for path, content in files.items():
    if content != originals[path]:
        (ROOT / path).write_text(content, encoding="utf-8", newline="\n")

api_target = ROOT / API_PATH
api_target.parent.mkdir(parents=True, exist_ok=True)
api_target.write_text(API_CONTENT, encoding="utf-8", newline="\n")

print("SUCCESS: faded-corpse targeting and Ghost Whisper rules applied.")
print("Backup:", backup)
print("No Supabase SQL is required.")
print("Now run: npm run build")
